{
  "sql": "SELECT treatment_arm, COUNT(DISTINCT subject_id) AS serious_adverse_events, COUNT(DISTINCT subject_id) FILTER (WHERE serious) AS serious_adverse_events_total, COUNT(DISTINCT subject_id) FILTER (WHERE serious) / COUNT(DISTINCT subject_id) AS serious_adverse_event_rate FROM adverse_events JOIN subjects ON adverse_events.subject_id = subjects.subject_id GROUP BY treatment_arm",
  "rationale": "The question asks to compare serious adverse-event rates across treatment arms. We need to count distinct subjects with serious adverse events and divide by total distinct enrolled subjects per treatment arm. The denominator is the total enrolled subjects (screening_status IN ('Enrolled', 'Randomized')) as per business definition. We join adverse_events to subjects to link treatment_arm, then group by treatment_arm to compute rate. The result includes numerator, denominator, and rate for each arm."
}

